const icons = { train: '▣', star: '✦', fire: '♨', arrow: '→', check: '✓', lock: '▣', map: '⌘' }

function Mascot({ small = false }: { small?: boolean }) { return <div className={`mascot ${small ? 'small' : ''}`} role="img" aria-label="Commu, mentor transit"><span className="cap">C</span><span className="mascot-ear left"/><span className="mascot-ear right"/><span className="face"><i className="eye left"/><i className="eye right"/><i className="smile"/></span><span className="antenna"/></div> }
function Network({ focus = 'dukuh' }: { focus?: string }) { return <svg className="network" viewBox="0 0 360 220" role="img" aria-label="Diagram jaringan LRT Jabodebek dan MRT Jakarta">
  <path className="line lrt" d="M24 168 C82 170 101 126 145 126 S205 93 220 68" />
  <path className="line mrt" d="M220 68 C242 86 268 114 326 53" />
  <path className="line tj" d="M220 68 C255 47 301 43 335 26" />
  {[[24,168,'Bekasi'],[145,126,'Cawang'],[220,68,'Dukuh Atas'],[326,53,'Blok M']].map(([x,y,label]) => <g key={String(label)}><circle className={String(label).toLowerCase().includes(focus) ? 'node active' : 'node'} cx={Number(x)} cy={Number(y)} r="10"/><text x={Number(x)} y={Number(y)+24}>{label}</text></g>)}
</svg> }
function Topbar({ profile, back, title }: { profile: Profile; back?: () => void; title?: string }) { return <header className="topbar">
  {back ? <button className="icon-btn" onClick={back} aria-label="Kembali">←</button> : <Mascot small />}
  <div className="title-area">{title ? <><span className="eyebrow">Dukuh Atas Explorer</span><strong>{title}</strong></> : <><strong>Halo, Penjelajah!</strong><span>Yuk pahami jaringan kota.</span></>}</div>
  <div className="top-stats"><span><b>{icons.fire}</b>{profile.streak}<small>streak</small></span><span><b>{icons.star}</b>{profile.xp}<small>XP</small></span></div>
</header> }
function playFeedback(ok: boolean, enabled: boolean) {
  if (!enabled) return
  const AudioContext = window.AudioContext || (window as Window & { webkitAudioContext?: typeof window.AudioContext }).webkitAudioContext
  if (!AudioContext) return
  const context = new AudioContext(); const oscillator = context.createOscillator(); const gain = context.createGain()
  oscillator.frequency.value = ok ? 660 : 190; gain.gain.value = 0.045; oscillator.connect(gain).connect(context.destination); oscillator.start(); oscillator.stop(context.currentTime + 0.11)
}
function playChainCue(cue: 'move' | 'combo' | 'soft' | 'break' | 'hub', enabled: boolean) {
  if (!enabled) return
  const AudioContext = window.AudioContext || (window as Window & { webkitAudioContext?: typeof window.AudioContext }).webkitAudioContext
  if (!AudioContext) return
  const tones = { move: [470, .06], combo: [760, .09], soft: [260, .1], break: [150, .14], hub: [880, .16] } as const
  const [frequency, duration] = tones[cue]; const context = new AudioContext(); const oscillator = context.createOscillator(); const gain = context.createGain()
  oscillator.frequency.value = frequency; oscillator.type = cue === 'break' ? 'sawtooth' : 'sine'; gain.gain.value = .045; oscillator.connect(gain).connect(context.destination); oscillator.start(); oscillator.stop(context.currentTime + duration)
}

function App() {
  const [profile, setProfile] = useState<Profile>(() => readProfile())
  const [screen, setScreen] = useState<Screen>(profile.onboarded ? 'learn' : 'welcome')
  const [gameIndex, setGameIndex] = useState(0)
  const [chainScenarioId, setChainScenarioId] = useState('dukuh-blokm')
  const [atlasPractice, setAtlasPractice] = useState<RoutePracticeScenario | null>(null)
  const [exploreStationId, setExploreStationId] = useState<string | undefined>()
  const [result, setResult] = useState<{ challenge: Challenge; ok: boolean; message: string; rewardEarned: number; chainSummary?: ChainRunSummary; pipeSummary?: PipeRushRunSummary; isNewPipeBest?: boolean } | null>(null)
  const save = (p: Profile) => { setProfile(p); writeProfile(p) }
  useEffect(() => { if ('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').catch(() => undefined) }, [])
  const completed = profile.completed.length
  const start = (onboardingPath: NonNullable<Profile['onboardingPath']> = 'new') => { save({ ...profile, onboarded: true, onboardingPath, demoMode: false }); setScreen('learn') }
  const startDemo = () => { save(demoProfile); setGameIndex(0); setScreen('lesson') }
  const finish = (challenge: Challenge, ok: boolean, expired = false, summary?: ChainRunSummary | PipeRushRunSummary) => {
    const chainSummary = summary && 'maxCombo' in summary ? summary : undefined
    const pipeSummary = summary && 'stars' in summary ? summary : undefined
    const chainClaim = chainSummary && ok ? claimChainScenarioReward(profile, chainSummary.scenarioId, chainSummary.reward) : { profile, rewardEarned: 0, firstCompletion: false }
    const pipeClaim = pipeSummary && ok ? claimPipeRushReward(profile, challenge.id, pipeSummary.scenarioId, pipeSummary.durationMs, pipeSummary.baseReward + pipeSummary.perfectBonus) : { profile, rewardEarned: 0, firstCompletion: false, isNewBest: false }
    const challengeAlready = profile.completed.includes(challenge.id)
    const rewardEarned = chainSummary ? chainClaim.rewardEarned : pipeSummary ? pipeClaim.rewardEarned : ok && !challengeAlready ? challenge.reward : 0
    const rewardProfile = chainSummary ? chainClaim.profile : pipeSummary ? pipeClaim.profile : profile
    const updated: Profile = {
      ...rewardProfile,
      xp: chainSummary || pipeSummary ? rewardProfile.xp : profile.xp + rewardEarned,
      completed: ok && !challengeAlready ? [...profile.completed, challenge.id] : profile.completed,
      completedChainScenarioIds: rewardProfile.completedChainScenarioIds,
      attempts: [...profile.attempts, {
        challengeId: challenge.id, scenarioId: chainSummary?.scenarioId ?? pipeSummary?.scenarioId, outcome: ok ? 'correct' : 'wrong', durationMs: chainSummary?.durationMs ?? pipeSummary?.durationMs ?? 0,
        mistakes: chainSummary?.softMistakes ?? (pipeSummary ? Math.max(0, pipeSummary.stepsUsed - pipeSummary.minSteps) : ok ? 0 : 1), maxCombo: chainSummary?.maxCombo,
        softMistakes: chainSummary?.softMistakes, hardBreaks: chainSummary?.hardBreaks, timeouts: chainSummary?.timeouts, efficiency: chainSummary?.efficiency,
      }],
    }
    save(updated); playFeedback(ok, profile.sound); setResult({ challenge, ok, chainSummary, pipeSummary, isNewPipeBest: pipeClaim.isNewBest, rewardEarned, message: ok ? 'Rute kamu tersambung!' : expired ? 'Waktu habis—coba lagi dan ikuti KRL Bogor hingga Kota.' : 'Belum tepat—coba lihat koneksinya lagi.' }); setScreen('result')
  }
  const game = challenges[gameIndex]
  return <main className={`app-shell ${screen === 'welcome' ? 'onboarding-shell' : ''} ${screen === 'atlas' || screen === 'atlas-practice' ? 'atlas-shell' : ''}`}>
    {screen === 'welcome' && <Welcome profile={profile} onStart={start} onDemo={startDemo} />}
    {screen === 'learn' && <LearningPath profile={profile} onOpenExplore={() => setScreen('explore')} onUpdateLessonProgress={(id, lessonProgress) => save({ ...profile, lessonProgress: { ...(profile.lessonProgress ?? {}), [id]: lessonProgress } })} onCompleteLesson={(id, lessonProgress) => !profile.completedLessons?.includes(id) && save({ ...profile, completedLessons: [...(profile.completedLessons ?? []), id], lessonProgress: { ...(profile.lessonProgress ?? {}), [id]: lessonProgress }, xp: profile.xp + 20 })} />}
    {screen === 'explore' && <Explore profile={profile} onBackToLearn={() => setScreen('learn')} initialStopId={exploreStationId} />}
    {screen === 'atlas' && <Atlas onOpenPractice={(scenario) => { setAtlasPractice(scenario); setScreen('atlas-practice') }} onLearnStation={(stationId) => { setExploreStationId(stationId); setScreen('explore') }} />}
    {screen === 'atlas-practice' && atlasPractice && <AtlasRoutePractice scenario={atlasPractice} onBack={() => setScreen('atlas')} />}
    {screen === 'lesson' && <Lesson profile={profile} onBack={() => setScreen('learn')} onPlay={() => { setGameIndex(1); setChainScenarioId('dukuh-blokm'); setScreen('game') }} />}
    {screen === 'main' && <MainGameHub profile={profile} onPlayPipe={() => { setGameIndex(0); setScreen('game') }} onPlayChain={() => { setGameIndex(1); setChainScenarioId('dukuh-blokm'); setScreen('game') }} />}
    {screen === 'game' && <Game challenge={game} profile={profile} initialChainScenarioId={chainScenarioId} onBack={() => setScreen('learn')} onFinish={finish} />}
    {screen === 'result' && result && <Result profile={profile} result={result} onNext={() => { if (result.chainSummary) { setScreen('game'); return } if (gameIndex < challenges.length - 1) { setGameIndex(gameIndex + 1); setScreen('game') } else setScreen('progress') }} onRetry={() => setScreen('game')} />}
    {screen === 'progress' && <Progress profile={profile} onBack={() => setScreen('learn')} onToggleSound={() => save({ ...profile, sound: !profile.sound })} onInspect={() => setScreen('inspector')} onReset={() => { resetProfile(); save(defaultProfile); setGameIndex(0); setScreen('welcome') }} />}
    {screen === 'inspector' && <Inspector profile={profile} onBack={() => setScreen('progress')} />}
    {screen !== 'welcome' && <Nav screen={screen} setScreen={setScreen} onOpenMain={() => setScreen('main')} />}
  </main>
}

